package edu.alliance.medislot.dao;import java.sql.*;import java.util.*;public class DoctorDao{public List<Map<String,Object>> all()throws SQLException{List<Map<String,Object>> a=new ArrayList<>();String q="SELECT u.id,u.name,u.email,d.specialty,d.experience,d.fee,d.rating,d.avatar FROM users u JOIN doctor_profiles d ON u.id=d.user_id";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong(1));m.put("name",r.getString(2));m.put("email",r.getString(3));m.put("specialty",r.getString(4));m.put("experience",r.getInt(5));m.put("fee",r.getBigDecimal(6));m.put("rating",r.getBigDecimal(7));m.put("avatar",r.getString(8));a.add(m);}}return a.stream().sorted(Comparator.comparing(x->(String)x.get("name"))).toList();}}